SELECT id, price, UNIX_TIMESTAMP(observed_at) AS obs_epoch, UNIX_TIMESTAMP(created_at) AS created_epoch, ROUND(UNIX_TIMESTAMP(created_at)-UNIX_TIMESTAMP(observed_at),3) AS ingest_lag_s, source, delivery_status, outcome_reason, ordering_slot FROM crypto_ai.market_price_event WHERE symbol='EGLDUSDT' AND observed_at BETWEEN FROM_UNIXTIME(1791747598) AND FROM_UNIXTIME(1791747840) ORDER BY observed_at, id LIMIT 200;